        return new int[0];
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<String> lines = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) lines.add(line);
        int pos = 0;
        int temperaturesLen = Integer.parseInt(lines.get(pos++).trim());
        int[] temperatures = new int[temperaturesLen];
        if (temperaturesLen > 0) {
            StringTokenizer st = new StringTokenizer(lines.get(pos));
            for (int i = 0; i < temperaturesLen; i++) temperatures[i] = Integer.parseInt(st.nextToken());
        }
        pos++;
        int[] result = solve(temperatures);
        System.out.println(Arrays.stream(result).mapToObj(String::valueOf).collect(Collectors.joining(" ")));
    }
}

